/// WGSL `true` / `false`. The keyword is a child token of the
/// `bool_literal`, not its text — a lift that spelled it as
/// text coparsed identically and matched nothing.
pub fn wgsl_bool_term(b: bool) -> Arc<QTerm> {
    if b {
        tb("bool_literal").c(&sym("true")).b()
    } else {
        tb("bool_literal").c(&sym("false")).b()
    }
}
impl LiftTo<Wgsl> for bool {
    fn lift_to(&self) -> Arc<QTerm> {
        wgsl_bool_term(*self)
    }
}
