/// Bash `"s"`. Double-quoted so the value is inert data:
/// everything the shell would interpret inside `"…"` is
/// backslash-escaped first.
pub fn bash_string_term(s: &str) -> Arc<QTerm> {
    if s.is_empty() {
        tb("string").c(&sym("\"")).c(&sym("\"")).b()
    } else {
        tb("string")
            .c(&sym("\""))
            .c(&leaf("string_content", &sh_dquote_escape(s)))
            .c(&sym("\""))
            .b()
    }
}
impl LiftTo<Bash> for str {
    fn lift_to(&self) -> Arc<QTerm> {
        bash_string_term(self)
    }
}
impl LiftTo<Bash> for String {
    fn lift_to(&self) -> Arc<QTerm> {
        bash_string_term(self)
    }
}
