/// Nix `true` / `false`. They are builtins rather than
/// keywords, so the parser reads them as a variable reference
/// and the name is its own node.
pub fn nix_bool_term(b: bool) -> Arc<QTerm> {
    if b {
        tb("variable_expression").c(&leaf("identifier", "true")).b()
    } else {
        tb("variable_expression")
            .c(&leaf("identifier", "false"))
            .b()
    }
}
impl LiftTo<Nix> for bool {
    fn lift_to(&self) -> Arc<QTerm> {
        nix_bool_term(*self)
    }
}
/// Nix `"s"`. Besides `"` and `\`, the antiquotation opener is
/// escaped, so the value stays data rather than interpolating.
pub fn nix_string_term(s: &str) -> Arc<QTerm> {
    if s.is_empty() {
        tb("string_expression").c(&sym("\"")).c(&sym("\"")).b()
    } else {
        tb("string_expression")
            .c(&sym("\""))
            .c(&leaf("string_fragment", &nix_dquote_escape(s)))
            .c(&sym("\""))
            .b()
    }
}
impl LiftTo<Nix> for str {
    fn lift_to(&self) -> Arc<QTerm> {
        nix_string_term(self)
    }
}
impl LiftTo<Nix> for String {
    fn lift_to(&self) -> Arc<QTerm> {
        nix_string_term(self)
    }
}
/// The container shape, with the elements as a parameter. Derived from
/// the empty, one- and two-element samples: what surrounds the first
/// element is the opener, what sits between two of them is the
/// separator, and what the empty container still writes is neither.
pub fn nix_list_term(items: &[Arc<QTerm>]) -> Arc<QTerm> {
    let mut b = tb("list_expression");
    b.child(&sym("["));
    b.write(" ");
    for (i, x) in items.iter().enumerate() {
        if i > 0 {
            b.write(" ");
        }
        b.child(x);
    }
    if !items.is_empty() {
        b.write(" ");
    }
    b.child(&sym("]"));
    b.b()
}
impl<T: LiftTo<Nix>> LiftTo<Nix> for [T] {
    fn lift_to(&self) -> Arc<QTerm> {
        nix_list_term(&self.iter().map(|x| x.lift_to()).collect::<Vec<_>>())
    }
}
impl<T: LiftTo<Nix>> LiftTo<Nix> for Vec<T> {
    fn lift_to(&self) -> Arc<QTerm> {
        self.as_slice().lift_to()
    }
}
/// Lean `3` and `-3`. `Nat`/`Int` are arbitrary-precision, so
/// every Rust integer width lifts losslessly; `num_lit` itself
/// is unsigned, so the sign is a node rather than a character.
pub fn lean_num_term(negative: bool, text: &str) -> Arc<QTerm> {
    if negative {
        tb("unary_op").c(&sym("-")).c(&leaf("num_lit", text)).b()
    } else {
        leaf("num_lit", text)
    }
}
