/// Lean `1.5` and `-1.5`.
pub fn lean_float_term(negative: bool, text: &str) -> Arc<QTerm> {
    if negative {
        tb("unary_op")
            .c(&sym("-"))
            .c(&leaf("scientific_lit", text))
            .b()
    } else {
        leaf("scientific_lit", text)
    }
}
impl LiftTo<Lean> for f32 {
    fn lift_to(&self) -> Arc<QTerm> {
        {
            let s = format!("{self:?}");
            match s.strip_prefix('-') {
                Some(mag) => lean_float_term(true, mag),
                None => lean_float_term(false, &s),
            }
        }
    }
}
impl LiftTo<Lean> for f64 {
    fn lift_to(&self) -> Arc<QTerm> {
        {
            let s = format!("{self:?}");
            match s.strip_prefix('-') {
                Some(mag) => lean_float_term(true, mag),
                None => lean_float_term(false, &s),
            }
        }
    }
}
